return ['domain'=>'nitrosearch','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'uk','project-id-version'=>'NitroSearch for WooCommerce','pot-creation-date'=>'2026-08-15T09:09:15+00:00','po-revision-date'=>'2026-08-08 16:58+0000','messages'=>['NitroSearch for WooCommerce'=>'NitroSearch for WooCommerce','https://nitrosearch.io'=>'https://nitrosearch.io','Blazing-fast hosted search for WooCommerce. Syncs your catalog to NitroSearch and replaces the default WordPress search with instant, typo-tolerant results.'=>'Блискавичний хмарний пошук для WooCommerce. Синхронізує ваш каталог із NitroSearch і замінює типовий пошук WordPress миттєвими результатами, стійкими до одруків.','WebDeviant'=>'WebDeviant','https://webdeviant.io'=>'https://webdeviant.io','<strong>NitroSearch now measures how your store\'s search performs</strong> — anonymous, cookieless counts of searches and result clicks, with no shopper identifiers. It helps result ranking improve, and per-store reporting is on the roadmap.'=>'<strong>NitroSearch тепер вимірює, як працює пошук у вашому магазині</strong> — анонімні підрахунки пошуків і кліків за результатами, без файлів cookie та без ідентифікаторів покупців. Це допомагає покращувати ранжування результатів, а звіти для кожного магазину вже в планах.','Manage it under %s.'=>'Керуйте цим у розділі %s.','NitroSearch → Appearance'=>'NitroSearch → Зовнішній вигляд','Dismiss'=>'Приховати','Unauthorized.'=>'Не авторизовано.','Not connected'=>'Не під’єднано','Confirming control…'=>'Підтверджуємо контроль…','Connected & verified'=>'Під’єднано й перевірено','Amazon-quality search for WooCommerce'=>'Пошук рівня Amazon для WooCommerce','Connect your store'=>'Під’єднайте свій магазин','Connect this store to NitroSearch to start syncing your catalog and serving instant, typo-tolerant search. Nothing leaves your site until you click Connect.'=>'Під’єднайте цей магазин до NitroSearch, щоб почати синхронізацію каталогу й отримати миттєвий пошук, стійкий до одруків. Ніщо не залишає ваш сайт, доки ви не натиснете «Під’єднати».','Provisioning token'=>'Токен під’єднання','Optional. Only needed if you were given a token to connect this store.'=>'Необов’язково. Потрібен, лише якщо вам видали токен для під’єднання цього магазину.','Connect store'=>'Під’єднати магазин','Confirming control of your site…'=>'Підтверджуємо контроль над вашим сайтом…','We’re verifying that you control this store before building your search index. In production this is automatic; if your site isn’t reachable from our servers it can take a moment. Your catalog syncs as soon as it’s confirmed.'=>'Ми перевіряємо, що ви контролюєте цей магазин, перш ніж будувати ваш пошуковий індекс. На робочому сайті це відбувається автоматично; якщо ваш сайт недоступний з наших серверів, це може забрати хвилину. Каталог синхронізується одразу після підтвердження.','Check status'=>'Перевірити стан','Disconnect'=>'Від’єднати','Dashboard'=>'Майстерня','Design'=>'Дизайн','You’ve reached your plan’s limit.'=>'Ви досягли ліміту свого тарифного плану.','Your search keeps running for everything already indexed, but new items won’t be added until you upgrade. Your products always take priority, so anything held back is a page or a post. Open %s below to move to a bigger plan.'=>'Пошук і далі працює для всього, що вже проіндексовано, але нові елементи не додаватимуться, доки ви не підвищите план. Ваші товари завжди в пріоритеті, тож якщо щось і затрималося, то це сторінка або запис. Відкрийте %s нижче, щоб перейти на більший план.','Manage / Upgrade'=>'Керувати / Підвищити план','Sync health'=>'Стан синхронізації','Search results indexed'=>'Проіндексовано результатів пошуку','Unlimited'=>'Без обмежень','Pending changes'=>'Зміни в черзі','Last sync'=>'Остання синхронізація','Never'=>'Ніколи','Last error'=>'Остання помилка','Sync all products'=>'Синхронізувати всі товари','Refresh status'=>'Оновити стан','%s from now'=>'через %s','On demand'=>'За запитом','unit: millisecondsms'=>'мс','Sync performance'=>'Продуктивність синхронізації','Avg sync speed'=>'Середня швидкість синхронізації','Last batch'=>'Останній пакет','Items synced'=>'Синхронізовано елементів','Batches sent'=>'Надіслано пакетів','Next sync'=>'Наступна синхронізація','Changes to your catalog are batched and pushed in the background — these figures show how quickly they reach your search index.'=>'Зміни у вашому каталозі групуються в пакети й надсилаються у фоновому режимі — ці цифри показують, як швидко вони потрапляють до вашого пошукового індексу.','Search analytics'=>'Аналітика пошуку','last 30 days'=>'останні 30 днів','Couldn’t load analytics just now — it will retry automatically.'=>'Не вдалося завантажити аналітику просто зараз — спроба повториться автоматично.','<strong>%1$s</strong> on your store in the last 30 days. See what shoppers searched for, what they clicked, and what they looked for and didn’t find — included on every paid plan, from %2$s.'=>'<strong>%1$s</strong> у вашому магазині за останні 30 днів. Дізнайтеся, що шукали покупці, на що вони клікали і що шукали, але не знайшли — доступно на кожному платному плані, від %2$s.','%s search'=>'%s пошуковий запит' . "\0" . '%s пошукові запити' . "\0" . '%s пошукових запитів','%s/mo'=>'%s/міс.','Upgrade to unlock'=>'Підвищіть план, щоб відкрити','Analytics starts collecting with plugin 1.5.0+ active — data appears within a few hours of shoppers searching.'=>'Аналітика збирається, коли активний плагін версії 1.5.0+ — дані з’являються протягом кількох годин після того, як покупці почнуть шукати.','Searches'=>'Пошукові запити','Zero-result rate'=>'Частка запитів без результатів','Click-through'=>'Клікабельність','Top searches'=>'Найпопулярніші запити','Searched, found nothing'=>'Шукали, але не знайшли','View full analytics →'=>'Переглянути повну аналітику →','Your plan & account'=>'Ваш план і обліковий запис','This store is claimed to a NitroSearch account. Manage your plan and billing from your NitroSearch dashboard.'=>'Цей магазин прив’язано до облікового запису NitroSearch. Керуйте своїм планом і оплатою з панелі керування NitroSearch.','You\'re on the <strong>Free</strong> plan. Claim this store to a NitroSearch account to manage it or upgrade — your index and search stay exactly as they are.'=>'Ви на плані <strong>Безкоштовний</strong>. Прив’яжіть цей магазин до облікового запису NitroSearch, щоб керувати ним або підвищити план — ваш індекс і пошук залишаться такими, як є.','Roomy'=>'Просторий','Two-line names and a clear picture. The default.'=>'Назви у два рядки та чітке зображення. Типовий варіант.','Compact'=>'Компактний','Smaller rows, so more products fit before scrolling.'=>'Менші рядки — більше товарів видно без прокручування.','Big pictures'=>'Великі зображення','Larger thumbnails for image-led catalogs.'=>'Більші мініатюри для каталогів, де головне — зображення.','Text only'=>'Лише текст','No pictures — good for spare parts and B2B.'=>'Без зображень — добре для запчастин, деталей і B2B.','Light'=>'Світла','A white panel. Suits most themes.'=>'Біла панель. Пасує більшості тем.','Dark'=>'Темна','A dark panel, for dark headers and themes.'=>'Темна панель — для темних шапок і тем.','Automatic'=>'Автоматично','Follows each shopper\'s own device setting.'=>'Відповідає налаштуванню пристрою кожного покупця.','Custom'=>'Власна','Choose your own panel and text colors below.'=>'Виберіть власні кольори панелі й тексту нижче.','Look'=>'Вигляд','Layout'=>'Макет','Products shown'=>'Кількість товарів','How many products appear in the drop-down as your shopper types.'=>'Скільки товарів з’являється в розкривному списку, поки покупець вводить запит.','Filters'=>'Фільтри','Automatic (recommended)'=>'Автоматично (рекомендовано)','Always across the top'=>'Завжди вгорі','Hide in the drop-down'=>'Приховати в розкривному списку','In stock, on sale, brand and category filters. Automatic puts them in a side column when there is room, and across the top when there is not.'=>'Фільтри «В наявності», «Зі знижкою», за брендом і категорією. «Автоматично» розміщує їх у бічній колонці, коли є місце, і вгорі, коли місця немає.','Drop-down width'=>'Ширина розкривного списку','Wide'=>'Широкий','Match my search box'=>'Як моє поле пошуку','Automatic gives product names enough room to read, even when your theme\'s search box is narrow. Match my search box keeps it exactly as wide as the box.'=>'«Автоматично» дає назвам товарів достатньо місця для читання, навіть якщо поле пошуку вашої теми вузьке. «Як моє поле пошуку» тримає список точно такої ширини, як саме поле.','Colors'=>'Кольори','Color scheme'=>'Кольорова схема','Accent color'=>'Акцентний колір','Used for prices, highlights and selected filters. Leave blank for the default. Text on top of it is set to black or white automatically, whichever stays readable.'=>'Використовується для цін, підсвічування та вибраних фільтрів. Залиште порожнім, щоб застосувати типовий колір. Текст поверх нього автоматично стає чорним або білим — залежно від того, що краще читається.','Panel background'=>'Фон панелі','Only used when the color scheme is set to Custom.'=>'Використовується, лише коли кольорову схему встановлено на «Власна».','Text color'=>'Колір тексту','Corners'=>'Кути','Rounded'=>'Заокруглені','Slightly rounded'=>'Трохи заокруглені','Square'=>'Прямі','Text style'=>'Стиль тексту','Match my store'=>'Як у моєму магазині','System default'=>'Системний шрифт','Custom font'=>'Власний шрифт','Match my store borrows the font your theme already uses around the search box.'=>'«Як у моєму магазині» запозичує шрифт, який ваша тема вже використовує навколо поля пошуку.','example font stacke.g. Georgia, serif'=>'напр. Georgia, serif','Only used when Custom font is selected.'=>'Використовується, лише коли вибрано «Власний шрифт».','What to search'=>'Що шукати','Include'=>'Включати','Products'=>'Товари','always indexed'=>'індексуються завжди','Pages'=>'Сторінки','Blog posts'=>'Записи блогу','Pages and posts count toward the same allowance as your products, so switching them off frees it up for your catalog. Your products always come first and are never displaced by them. Private, password-protected and unpublished content is never indexed, and we honor %s set by Yoast SEO or Rank Math (per item, per content type, or site-wide).'=>'Сторінки й записи рахуються в той самий ліміт, що й ваші товари, тож їх вимкнення звільняє місце для каталогу. Ваші товари завжди на першому місці й ніколи ними не витісняються. Приватний, захищений паролем і неопублікований вміст ніколи не індексується, а ще ми поважаємо %s, встановлений через Yoast SEO або Rank Math (для окремого елемента, типу вмісту або всього сайту).','Search results page'=>'Сторінка результатів пошуку','Enhance the product search results page with NitroSearch results and filters'=>'Покращити сторінку результатів пошуку товарів результатами й фільтрами NitroSearch','Privacy &amp; credit'=>'Приватність і згадка','Search usage data'=>'Дані про використання пошуку','Share anonymous search usage counts with NitroSearch'=>'Ділитися з NitroSearch анонімними підрахунками використання пошуку','Counts searches, result totals and result clicks on your store\'s search — cookieless and anonymous, with no shopper identifiers, no IP addresses and nothing stored in the shopper\'s browser. Used to improve result ranking and to power your search analytics. Uncheck to stop sending immediately.'=>'Підраховує пошуки, кількість результатів і кліки за результатами в пошуку вашого магазину — анонімно й без файлів cookie, без ідентифікаторів покупців, без IP-адрес і без збереження будь-чого в браузері покупця. Використовується, щоб покращувати ранжування результатів і живити вашу аналітику пошуку. Зніміть позначку, щоб негайно припинити надсилання.','Powered-by credit'=>'Згадка «Працює на NitroSearch»','Show a small “Powered by NitroSearch” credit, linking to nitrosearch.io'=>'Показувати невелику згадку «Працює на NitroSearch» з посиланням на nitrosearch.io','Off by default, and entirely your choice. Turning it on adds a small credit in the search box and one line in your site footer, both linking to %s — a normal, followed link. Nothing is added to your site unless you check this. Thank you if you do.'=>'Типово вимкнено, і вибір цілком за вами. Якщо ввімкнути, у полі пошуку з’явиться невелика згадка, а в підвалі сайту — один рядок, обидва з посиланням на %s — звичайним посиланням, без nofollow. Ніщо не додається на ваш сайт, доки ви не поставите цю позначку. Дякуємо, якщо поставите.','Advanced'=>'Додатково','Search box selector'=>'Селектор поля пошуку','example CSS selectore.g. input.my-theme-search'=>'напр. input.my-theme-search','Optional CSS selector for your theme\'s search input. Leave blank to auto-detect.'=>'Необов’язковий CSS-селектор поля пошуку вашої теми. Залиште порожнім для автовизначення.','Save design'=>'Зберегти дизайн','Connect failed: %s'=>'Не вдалося під’єднатися: %s','unknown error'=>'невідома помилка','Connected and verified.'=>'Під’єднано й перевірено.','Connected. Confirming control of your site — this can take a moment. Use “Check status” below if it doesn’t update.'=>'Під’єднано. Підтверджуємо контроль над вашим сайтом — це може тривати хвилину. Скористайтеся кнопкою «Перевірити стан» нижче, якщо стан не оновлюється.','Syncing %s product in the background, then your pages and posts.'=>'Синхронізуємо %s товар у фоновому режимі, потім ваші сторінки й записи.' . "\0" . 'Синхронізуємо %s товари у фоновому режимі, потім ваші сторінки й записи.' . "\0" . 'Синхронізуємо %s товарів у фоновому режимі, потім ваші сторінки й записи.','Syncing %s product in the background.'=>'Синхронізуємо %s товар у фоновому режимі.' . "\0" . 'Синхронізуємо %s товари у фоновому режимі.' . "\0" . 'Синхронізуємо %s товарів у фоновому режимі.','Verified!'=>'Перевірено!','%1$s search results indexed · %2$s pending.'=>'Проіндексовано результатів пошуку: %1$s · у черзі: %2$s.','Still confirming control of your site — please try again in a moment.'=>'Усе ще підтверджуємо контроль над вашим сайтом — спробуйте ще раз за мить.','Design saved.'=>'Дизайн збережено.','Saved. Removing your pages and blog posts from your index in the background.'=>'Збережено. Вилучаємо ваші сторінки та записи блогу з індексу у фоновому режимі.','Saved. Removing your pages from your index in the background.'=>'Збережено. Вилучаємо ваші сторінки з індексу у фоновому режимі.','Saved. Removing your blog posts from your index in the background.'=>'Збережено. Вилучаємо ваші записи блогу з індексу у фоновому режимі.','Saved. Indexing your pages and blog posts in the background.'=>'Збережено. Індексуємо ваші сторінки та записи блогу у фоновому режимі.','Saved. Indexing your pages in the background.'=>'Збережено. Індексуємо ваші сторінки у фоновому режимі.','Saved. Indexing your blog posts in the background.'=>'Збережено. Індексуємо ваші записи блогу у фоновому режимі.','Disconnected.'=>'Від’єднано.','This store is already claimed to a NitroSearch account.'=>'Цей магазин уже прив’язано до облікового запису NitroSearch.','We couldn’t confirm control of your site yet — click "Refresh status" first, then try again.'=>'Ми ще не змогли підтвердити контроль над вашим сайтом — спочатку натисніть «Оновити стан», а потім спробуйте ще раз.','Your site needs re-checking — click "Refresh status", then try again.'=>'Ваш сайт потребує повторної перевірки — натисніть «Оновити стан», а потім спробуйте ще раз.','Too many attempts — please wait a minute and try again.'=>'Забагато спроб — зачекайте хвилину та спробуйте ще раз.','Could not create a manage link. Please try again.'=>'Не вдалося створити посилання для керування. Спробуйте ще раз.','Insufficient permissions.'=>'Недостатньо прав.','Search powered by %s'=>'Пошук працює на %s','Refine results'=>'Уточнити результати','Refine'=>'Уточнити','In stock'=>'В наявності','On sale'=>'Зі знижкою','Brand'=>'Бренд','Category'=>'Категорія','View'=>'Переглянути','Add to cart'=>'Додати в кошик','Adding…'=>'Додаємо…','Added ✓'=>'Додано ✓','Try again'=>'Спробувати ще раз','Searching…'=>'Шукаємо…','Search is unavailable.'=>'Пошук недоступний.','Search is unavailable right now.'=>'Пошук зараз недоступний.','No products found.'=>'Товарів не знайдено.','No products found for “%s”.'=>'За запитом «%s» товарів не знайдено.','Nothing found for “%s”.'=>'За запитом «%s» нічого не знайдено.','Search products…'=>'Шукати товари…','Close search'=>'Закрити пошук','Product results'=>'Знайдені товари','Recent searches'=>'Нещодавні запити','Clear'=>'Очистити','Start typing to search products…'=>'Почніть вводити, щоб шукати товари…','Sale'=>'Розпродаж','Out of stock'=>'Немає в наявності','Pages & posts'=>'Сторінки й записи','a website page, shown on a search resultPage'=>'Сторінка','a blog post, shown on a search resultArticle'=>'Стаття','unit: milliseconds%s ms'=>'%s мс','Powered by %s'=>'Працює на %s','Page %1$s of %2$s'=>'Сторінка %1$s з %2$s','← Prev'=>'← Назад','Next →'=>'Далі →','button labelSearch'=>'Пошук','%s product found.'=>'Знайдено %s товар.' . "\0" . 'Знайдено %s товари.' . "\0" . 'Знайдено %s товарів.','See all %s result →'=>'Переглянути %s результат →' . "\0" . 'Переглянути всі %s результати →' . "\0" . 'Переглянути всі %s результатів →','%1$s result for “%2$s”'=>'%1$s результат за запитом «%2$s»' . "\0" . '%1$s результати за запитом «%2$s»' . "\0" . '%1$s результатів за запитом «%2$s»','%s result'=>'%s результат' . "\0" . '%s результати' . "\0" . '%s результатів']];